# C: strings (character arrays), 40 problems.
S = [("str", "s")]
S2 = [("str", "s"), ("str", "t")]
LINE = [("line", "s")]
T = "Strings"
W = "One word (up to 100 characters)."
L = "One line of text (up to 255 characters)."
IN = [("int", "n")]
LEN = '    int len = 0;\n    while (s[len]) len++;\n'
cq("c-str-echo-word", "Read and Print a Word", "EASY", T, "Read one word with `scanf` and print `You entered: <word>`.", W, "One line.", "1 <= length <= 100",
   '    printf("You entered: %s\\n", s);', ["hello", "NextByte", "a", "C2026", "programming"], S)
cq("c-str-read-line", "Read a Whole Line", "EASY", T, "`scanf(\"%s\")` stops at a space. Read a full line with `fgets` and print it back as `Line: <text>`.", L, "One line.", "At most 255 characters",
   '    printf("Line: %s\\n", s);', ["hello world", "one", "Next Byte is fun", "  spaced  out ", "a,b,c"], LINE)
cq("c-str-length-manual", "Length without strlen", "EASY", T, "Print how many characters the line has, counting with a loop (not `strlen`).", L, "The length.", "At most 255 characters",
   LEN + '    printf("%d\\n", len);', ["hello world", "a", "Next Byte", "", "12345 6789"], LINE)
cq("c-str-copy-manual", "Copy a String Manually", "EASY", T, "Copy the word into a second array with a loop (not `strcpy`) and print the copy.", W, "The copy.", "1 <= length <= 100",
   '    char t[101];\n    int i = 0;\n    for (; s[i]; i++) t[i] = s[i];\n    t[i] = \'\\0\';\n    printf("%s\\n", t);', ["hello", "a", "programming", "NextByte", "12345"], S)
cq("c-str-concat-manual", "Join Two Words Manually", "EASY", T, "Read two words and print them joined into one word, built with loops (not `strcat`).", "One line with two words.", "The joined word.", "Each word at most 50 characters",
   '    char out[202];\n    int k = 0;\n    for (int i = 0; s[i]; i++) out[k++] = s[i];\n    for (int i = 0; t[i]; i++) out[k++] = t[i];\n    out[k] = \'\\0\';\n    printf("%s\\n", out);', ["hello world", "a b", "Next Byte", "abc 123", "x y"], S2)
cq("c-str-compare-manual", "Compare Two Words Manually", "EASY", T, "Compare two words character by character (not `strcmp`). Print `Less`, `Equal` or `Greater` for dictionary order.", "One line with two words.", "One word.", "Each word at most 100 characters",
   '    int i = 0;\n    while (s[i] && s[i] == t[i]) i++;\n    if (s[i] == t[i]) printf("Equal\\n");\n    else if (s[i] < t[i]) printf("Less\\n");\n    else printf("Greater\\n");', ["apple banana", "banana apple", "same same", "abc abcd", "abcd abc"], S2)
cq("c-str-reverse", "Reverse a Word", "EASY", T, "Reverse the word in place by swapping characters from both ends. Print it.", W, "The reversed word.", "1 <= length <= 100",
   LEN + '    for (int i = 0, j = len - 1; i < j; i++, j--) {\n        char c = s[i];\n        s[i] = s[j];\n        s[j] = c;\n    }\n    printf("%s\\n", s);', ["hello", "a", "level", "NextByte", "12345"], S)
cq("c-str-to-upper", "Lowercase to Uppercase", "EASY", T, "Change every small letter in the line to a capital letter. Other characters stay the same.", L, "The new text.", "At most 255 characters",
   '    for (int i = 0; s[i]; i++) if (s[i] >= \'a\' && s[i] <= \'z\') s[i] -= 32;\n    printf("%s\\n", s);', ["hello world", "ABC", "Next Byte 2026", "mixed Case", "123 !!"], LINE)
cq("c-str-to-lower", "Uppercase to Lowercase", "EASY", T, "Change every capital letter in the line to a small letter. Other characters stay the same.", L, "The new text.", "At most 255 characters",
   '    for (int i = 0; s[i]; i++) if (s[i] >= \'A\' && s[i] <= \'Z\') s[i] += 32;\n    printf("%s\\n", s);', ["HELLO WORLD", "abc", "Next Byte 2026", "Mixed Case", "123 !!"], LINE)
cq("c-str-toggle-case", "Toggle the Case", "EASY", T, "Turn capitals into small letters and small letters into capitals. Other characters stay.", L, "The new text.", "At most 255 characters",
   '    for (int i = 0; s[i]; i++) {\n        if (s[i] >= \'a\' && s[i] <= \'z\') s[i] -= 32;\n        else if (s[i] >= \'A\' && s[i] <= \'Z\') s[i] += 32;\n    }\n    printf("%s\\n", s);', ["Hello World", "ABC", "Next Byte 2026", "mIxEd", "123 !!"], LINE)
cq("c-str-vowels-consonants", "Count Vowels and Consonants", "EASY", T, "Print `Vowels: <x>` and `Consonants: <y>` for the line. Count a e i o u (either case) as vowels and other letters as consonants.", L, "Two lines.", "At most 255 characters",
   '    int v = 0, c = 0;\n    for (int i = 0; s[i]; i++) {\n        char ch = s[i];\n        if (ch >= \'A\' && ch <= \'Z\') ch += 32;\n        if (ch == \'a\' || ch == \'e\' || ch == \'i\' || ch == \'o\' || ch == \'u\') v++;\n        else if (ch >= \'a\' && ch <= \'z\') c++;\n    }\n    printf("Vowels: %d\\nConsonants: %d\\n", v, c);', ["hello world", "AEIOU", "xyz", "Programming in C", "123 !!"], LINE)
cq("c-str-char-kinds", "Letters, Digits and Symbols", "EASY", T, "Print `Alphabets: <x>`, `Digits: <y>` and `Special: <z>` for the line. Everything that is not a letter or digit (spaces included) is special.", L, "Three lines.", "At most 255 characters",
   '    int a = 0, d = 0, o = 0;\n    for (int i = 0; s[i]; i++) {\n        char c = s[i];\n        if ((c >= \'a\' && c <= \'z\') || (c >= \'A\' && c <= \'Z\')) a++;\n        else if (c >= \'0\' && c <= \'9\') d++;\n        else o++;\n    }\n    printf("Alphabets: %d\\nDigits: %d\\nSpecial: %d\\n", a, d, o);', ["Hello World 123!", "abc", "12345", "a b c", "!@#$%"], LINE)
cq("c-str-count-words", "Count Words", "EASY", T, "Count the words in the line. Words are separated by one or more spaces.", L, "The word count.", "At most 255 characters",
   '    int words = 0, in = 0;\n    for (int i = 0; s[i]; i++) {\n        if (s[i] != \' \' && !in) { words++; in = 1; }\n        else if (s[i] == \' \') in = 0;\n    }\n    printf("%d\\n", words);', ["hello world", "one", "a  b   c", "Next Byte is fun", "  leading and trailing  "], LINE)
cq("c-str-is-palindrome", "Palindrome String", "EASY", T, "Print `Yes` if the word reads the same backwards, else `No`.", W, "`Yes` or `No`.", "1 <= length <= 100",
   LEN + '    int ok = 1;\n    for (int i = 0, j = len - 1; i < j; i++, j--) if (s[i] != s[j]) ok = 0;\n    printf("%s\\n", ok ? "Yes" : "No");', ["level", "hello", "a", "abba", "noon1"], S)
cq("c-str-char-frequency", "Frequency of Each Character", "MEDIUM", T, "For every character of the line except spaces, in order of first appearance, print `<char>: <count>` on its own line.", L, "One line per distinct character.", "At most 255 characters",
   '    int done[256] = {0};\n    for (int i = 0; s[i]; i++) {\n        unsigned char c = s[i];\n        if (c == \' \' || done[c]) continue;\n        int count = 0;\n        for (int j = i; s[j]; j++) if (s[j] == s[i]) count++;\n        done[c] = 1;\n        printf("%c: %d\\n", c, count);\n    }', ["hello world", "aaa", "abcabc", "banana", "a b a"], LINE)
cq("c-str-remove-vowels", "Remove the Vowels", "EASY", T, "Print the line with every vowel (a e i o u, either case) removed.", L, "The new text.", "At most 255 characters",
   '    char out[256];\n    int k = 0;\n    for (int i = 0; s[i]; i++) {\n        char c = s[i];\n        if (c >= \'A\' && c <= \'Z\') c += 32;\n        if (!(c == \'a\' || c == \'e\' || c == \'i\' || c == \'o\' || c == \'u\')) out[k++] = s[i];\n    }\n    out[k] = \'\\0\';\n    printf("%s\\n", out);', ["hello world", "AEIOU", "xyz", "Programming in C", "123 !!"], LINE)
cq("c-str-remove-spaces", "Remove the Spaces", "EASY", T, "Print the line with all spaces removed.", L, "The new text.", "At most 255 characters",
   '    char out[256];\n    int k = 0;\n    for (int i = 0; s[i]; i++) if (s[i] != \' \') out[k++] = s[i];\n    out[k] = \'\\0\';\n    printf("%s\\n", out);', ["hello world", "a b c", "nospaces", "  lead and trail  ", "x"], LINE)
cq("c-str-keep-alphabets", "Keep Only Letters", "EASY", T, "Print the line with everything removed except letters.", L, "The letters only.", "At most 255 characters",
   '    char out[256];\n    int k = 0;\n    for (int i = 0; s[i]; i++) {\n        char c = s[i];\n        if ((c >= \'a\' && c <= \'z\') || (c >= \'A\' && c <= \'Z\')) out[k++] = c;\n    }\n    out[k] = \'\\0\';\n    printf("%s\\n", out);', ["h3llo w0rld!", "abc", "12345", "a-b_c", "Next Byte 2026"], LINE)
cq("c-str-first-non-repeating", "First Non-Repeating Character", "MEDIUM", T, "Print the first character of the word that appears only once, or `None` if every character repeats.", W, "The character or `None`.", "1 <= length <= 100",
   '    for (int i = 0; s[i]; i++) {\n        int count = 0;\n        for (int j = 0; s[j]; j++) if (s[j] == s[i]) count++;\n        if (count == 1) {\n            printf("%c\\n", s[i]);\n            return 0;\n        }\n    }\n    printf("None\\n");', ["swiss", "aabb", "hello", "a", "abcabcd"], S)
cq("c-str-most-frequent-char", "Most Frequent Character", "MEDIUM", T, "Print the character that appears most often in the word. If there is a tie print the one that appears first in the word.", W, "One character.", "1 <= length <= 100",
   '    char best = s[0];\n    int bestCount = 0;\n    for (int i = 0; s[i]; i++) {\n        int count = 0;\n        for (int j = 0; s[j]; j++) if (s[j] == s[i]) count++;\n        if (count > bestCount) { bestCount = count; best = s[i]; }\n    }\n    printf("%c\\n", best);', ["hello", "aabb", "banana", "a", "mississippi"], S)
cq("c-str-sort-characters", "Sort the Characters", "MEDIUM", T, "Rearrange the letters of the word in increasing order of their ASCII code (so capitals come before small letters) and print it.", W, "The sorted word.", "1 <= length <= 100",
   LEN + '    for (int i = 0; i < len - 1; i++)\n        for (int j = 0; j < len - 1 - i; j++)\n            if (s[j] > s[j + 1]) { char t = s[j]; s[j] = s[j + 1]; s[j + 1] = t; }\n    printf("%s\\n", s);', ["hello", "a", "banana", "NextByte", "zyxw"], S)
cq("c-str-anagram", "Anagram Check", "MEDIUM", T, "Two words are anagrams when they use exactly the same letters the same number of times. Print `Yes` or `No` (the words use small letters only).", "One line with two words.", "`Yes` or `No`.", "Each word at most 100 characters",
   '    int count[26] = {0};\n    for (int i = 0; s[i]; i++) count[s[i] - \'a\']++;\n    for (int i = 0; t[i]; i++) count[t[i] - \'a\']--;\n    int ok = 1;\n    for (int i = 0; i < 26; i++) if (count[i] != 0) ok = 0;\n    printf("%s\\n", ok ? "Yes" : "No");', ["listen silent", "hello world", "abc cab", "aab abb", "a a"], S2)
cq("c-str-all-substrings", "All Substrings", "MEDIUM", T, "Print every substring of the word, one per line: first all that start at position 0 (shortest first), then those that start at position 1, and so on.", "One word (up to 8 characters).", "One substring per line.", "1 <= length <= 8",
   LEN + '    for (int i = 0; i < len; i++)\n        for (int j = i; j < len; j++) printf("%.*s\\n", j - i + 1, s + i);', ["abc", "a", "ab", "xyz", "abcd"], S)
cq("c-str-find-word", "Find a Word in a Sentence", "MEDIUM", T, "Read a sentence on the first line and a pattern word on the second. Print the 0-based index where the pattern first appears in the sentence, or `Not found`.", "Line 1 the sentence, line 2 the pattern.", "The index or `Not found`.", "At most 255 characters",
   '    for (int i = 0; s[i]; i++) {\n        int j = 0;\n        while (t[j] && s[i + j] == t[j]) j++;\n        if (t[j] == \'\\0\') {\n            printf("%d\\n", i);\n            return 0;\n        }\n    }\n    printf("Not found\\n");', ["the quick brown fox\nquick", "hello world\nxyz", "aaaa\naa", "abc\nabc", "abc\nabcd"], [("line", "s"), ("str", "t")])
cq("c-str-replace-char", "Replace a Character", "EASY", T, "Read a line, then two characters `from to` on the second line. Replace every `from` in the line by `to` and print the line.", "Line 1 the text, line 2 `from to`.", "The new text.", "At most 255 characters",
   '    for (int i = 0; s[i]; i++) if (s[i] == from) s[i] = to;\n    printf("%s\\n", s);', ["hello world\no 0", "banana\na o", "abc\nx y", "a-b-c\n- _", "same\ns s"], [("line", "s"), ("char", "from to")])
cq("c-str-trim", "Trim Spaces", "EASY", T, "Remove the spaces at the start and end of the line and print the result between square brackets, like `[text]`.", L, "The trimmed text in brackets.", "At most 255 characters",
   LEN + '    int start = 0, end = len - 1;\n    while (start < len && s[start] == \' \') start++;\n    while (end >= start && s[end] == \' \') end--;\n    printf("[%.*s]\\n", end - start + 1, s + start);', ["  hello world  ", "abc", "   x", "y   ", "     "], LINE)
cq("c-str-capitalize-words", "Capitalise Each Word", "MEDIUM", T, "Make the first letter of every word a capital letter. Leave the other letters as they are.", L, "The new text.", "At most 255 characters",
   '    for (int i = 0; s[i]; i++)\n        if ((i == 0 || s[i - 1] == \' \') && s[i] >= \'a\' && s[i] <= \'z\') s[i] -= 32;\n    printf("%s\\n", s);', ["hello world", "one", "next byte is fun", "a b c", "already Capital words"], LINE)
cq("c-str-rotation", "Is It a Rotation?", "MEDIUM", T, "A word is a rotation of another when you can get it by moving some letters from the front to the back (`abcd` and `cdab`). Print `Yes` or `No`.", "One line with two words.", "`Yes` or `No`.", "Each word at most 100 characters",
   '    int n = 0, m = 0, ok = 0;\n    while (s[n]) n++;\n    while (t[m]) m++;\n    if (n == m)\n        for (int shift = 0; shift < n && !ok; shift++) {\n            int same = 1;\n            for (int i = 0; i < n; i++) if (s[(i + shift) % n] != t[i]) same = 0;\n            if (same) ok = 1;\n        }\n    printf("%s\\n", ok ? "Yes" : "No");', ["abcd cdab", "abcd abdc", "a a", "ab abc", "hello llohe"], S2)
cq("c-str-longest-word", "Longest Word", "MEDIUM", T, "Print the longest word of the sentence (the first one if several have the same length).", L, "The word.", "At most 255 characters, at least one word",
   '    int best = 0, bestLen = 0, i = 0;\n    while (s[i]) {\n        while (s[i] == \' \') i++;\n        int start = i;\n        while (s[i] && s[i] != \' \') i++;\n        if (i - start > bestLen) { bestLen = i - start; best = start; }\n    }\n    printf("%.*s\\n", bestLen, s + best);', ["the quick brown fox", "one", "a bb cc", "short longest mid", "same four size"], LINE)
cq("c-str-remove-duplicate-chars", "Remove Repeated Characters", "MEDIUM", T, "Print the word keeping only the first occurrence of each character.", W, "The new word.", "1 <= length <= 100",
   '    char out[101];\n    int k = 0;\n    for (int i = 0; s[i]; i++) {\n        int seen = 0;\n        for (int j = 0; j < k; j++) if (out[j] == s[i]) seen = 1;\n        if (!seen) out[k++] = s[i];\n    }\n    out[k] = \'\\0\';\n    printf("%s\\n", out);', ["programming", "aaa", "abc", "mississippi", "hello"], S)
cq("c-str-count-substring", "Count a Substring", "MEDIUM", T, "Count how many times the pattern appears in the text (matches may not overlap). Read the text first, then the pattern, each a word.", "One line: `text pattern`.", "The count.", "Each word at most 100 characters",
   '    int count = 0, m = 0;\n    while (t[m]) m++;\n    for (int i = 0; s[i];) {\n        int j = 0;\n        while (j < m && s[i + j] == t[j]) j++;\n        if (j == m) { count++; i += m; }\n        else i++;\n    }\n    printf("%d\\n", count);', ["abababab ab", "aaaa aa", "hello xyz", "banana ana", "abc abc"], S2)
cq("c-str-reverse-words", "Reverse the Word Order", "MEDIUM", T, "Print the words of the sentence in reverse order, separated by single spaces.", L, "The reversed sentence.", "At most 255 characters",
   '    char *words[128];\n    int count = 0;\n    for (int i = 0; s[i];) {\n        while (s[i] == \' \') i++;\n        if (!s[i]) break;\n        words[count++] = s + i;\n        while (s[i] && s[i] != \' \') i++;\n        if (s[i]) s[i++] = \'\\0\';\n    }\n    for (int i = count - 1; i >= 0; i--) printf("%s%s", words[i], i ? " " : "\\n");', ["hello world", "one", "a b c", "Next Byte is fun", "  spaced   out  "], LINE)
cq("c-str-atoi", "String to Integer (atoi)", "MEDIUM", T, "Read a word that is a whole number (it may start with `-`) and convert it to an `int` yourself, digit by digit. Print the value plus 1 to show it is a real number.", "One word.", "The number plus one.", "The value fits in an int",
   '    int i = 0, sign = 1, value = 0;\n    if (s[0] == \'-\') { sign = -1; i = 1; }\n    for (; s[i]; i++) value = value * 10 + (s[i] - \'0\');\n    printf("%d\\n", sign * value + 1);', ["123", "-45", "0", "99999", "-1"], S)
cq("c-str-itoa", "Integer to String (itoa)", "MEDIUM", T, "Convert the integer to characters yourself (peel digits off with `% 10`), then print the text and its length as `<text> <length>`.", "One integer.", "`<text> <length>`.", "|n| <= 10^9",
   '    char buf[16];\n    int len = 0, neg = n < 0;\n    long long v = neg ? -(long long)n : n;\n    do {\n        buf[len++] = \'0\' + v % 10;\n        v /= 10;\n    } while (v > 0);\n    if (neg) buf[len++] = \'-\';\n    buf[len] = \'\\0\';\n    for (int i = 0, j = len - 1; i < j; i++, j--) { char t = buf[i]; buf[i] = buf[j]; buf[j] = t; }\n    printf("%s %d\\n", buf, len);', ["123", "-45", "0", "1000000000", "-7"], [("int", "n")])
cq("c-str-five-names", "Store Five Names", "EASY", T, "Read five names (one word each) into an array of strings and print them numbered, like `1. asha`.", "Five words, one per line.", "Five lines.", "Each name at most 30 characters",
   '    char names[5][31];\n    for (int i = 0; i < 5; i++) scanf("%30s", names[i]);\n    for (int i = 0; i < 5; i++) printf("%d. %s\\n", i + 1, names[i]);', ["asha\nravi\nmeena\nkiran\nsana", "a\nb\nc\nd\ne", "one\ntwo\nthree\nfour\nfive", "x\ny\nz\nw\nv", "Next\nByte\nIs\nVery\nFun"], ())
cq("c-str-sort-names", "Sort Words Alphabetically", "MEDIUM", T, "Read `n` words and print them in dictionary order (by ASCII code), one per line. Use `strcmp` and `strcpy`.", "First line `n`, then `n` words.", "The sorted words.", "1 <= n <= 100, each word at most 30 characters",
   '    char w[100][31];\n    for (int i = 0; i < n; i++) scanf("%30s", w[i]);\n    for (int i = 0; i < n - 1; i++)\n        for (int j = 0; j < n - 1 - i; j++)\n            if (strcmp(w[j], w[j + 1]) > 0) {\n                char t[31];\n                strcpy(t, w[j]);\n                strcpy(w[j], w[j + 1]);\n                strcpy(w[j + 1], t);\n            }\n    for (int i = 0; i < n; i++) printf("%s\\n", w[i]);', ["4\nbanana\napple\ncherry\napple", "1\nsolo", "3\nb\na\nc", "2\nabc\nab", "5\ne\nd\nc\nb\na"], [("int", "n")], inc="#include <string.h>\n")
cq("c-str-shortest-longest", "Shortest and Longest Word", "MEDIUM", T, "Read `n` words. Print `Shortest: <word>` and `Longest: <word>`; if several words tie, print the first of them.", "First line `n`, then `n` words.", "Two lines.", "1 <= n <= 100, each word at most 30 characters",
   '    char w[100][31];\n    int shortest = 0, longest = 0;\n    for (int i = 0; i < n; i++) {\n        scanf("%30s", w[i]);\n        if (strlen(w[i]) < strlen(w[shortest])) shortest = i;\n        if (strlen(w[i]) > strlen(w[longest])) longest = i;\n    }\n    printf("Shortest: %s\\nLongest: %s\\n", w[shortest], w[longest]);', ["4\nbanana\nfig\ncherry\napple", "1\nsolo", "3\nb\naa\ncc", "2\nabc\nxyz", "5\ne\ndd\nccc\nbbbb\naaaaa"], [("int", "n")], inc="#include <string.h>\n")
cq("c-str-email-check", "Simple Email Check", "MEDIUM", T, "Call a word a valid email when it has exactly one `@`, the `@` is not the first character, there is a `.` somewhere after the `@`, and the word does not end with `.`. Print `Valid` or `Invalid`.", W, "`Valid` or `Invalid`.", "1 <= length <= 100",
   '    int at = -1, atCount = 0, dotAfter = 0, len = 0;\n    for (int i = 0; s[i]; i++, len++) {\n        if (s[i] == \'@\') { atCount++; at = i; }\n        else if (s[i] == \'.\' && at >= 0) dotAfter = 1;\n    }\n    int ok = atCount == 1 && at > 0 && dotAfter && s[len - 1] != \'.\';\n    printf("%s\\n", ok ? "Valid" : "Invalid");', ["a@b.com", "abc.com", "@b.com", "a@b.", "a@@b.com", "name@site"], S)
cq("c-str-caesar-encrypt", "Caesar Cipher: Encrypt", "MEDIUM", T, "Shift every letter 3 places forward (`a` becomes `d`, `z` becomes `c`). Capitals stay capitals; other characters are unchanged. Print the result.", L, "The encrypted text.", "At most 255 characters",
   '    for (int i = 0; s[i]; i++) {\n        if (s[i] >= \'a\' && s[i] <= \'z\') s[i] = (s[i] - \'a\' + 3) % 26 + \'a\';\n        else if (s[i] >= \'A\' && s[i] <= \'Z\') s[i] = (s[i] - \'A\' + 3) % 26 + \'A\';\n    }\n    printf("%s\\n", s);', ["hello world", "xyz", "Next Byte 2026", "ABC", "abc, xyz!"], LINE)
cq("c-str-caesar-decrypt", "Caesar Cipher: Decrypt", "MEDIUM", T, "The text was encrypted by shifting every letter 3 places forward. Shift every letter 3 places back to get the original (`d` becomes `a`, `a` becomes `x`). Other characters stay.", L, "The original text.", "At most 255 characters",
   '    for (int i = 0; s[i]; i++) {\n        if (s[i] >= \'a\' && s[i] <= \'z\') s[i] = (s[i] - \'a\' + 23) % 26 + \'a\';\n        else if (s[i] >= \'A\' && s[i] <= \'Z\') s[i] = (s[i] - \'A\' + 23) % 26 + \'A\';\n    }\n    printf("%s\\n", s);', ["khoor zruog", "abc", "Qhaw Bwwh 2026", "DEF", "def, abc!"], LINE)
